function(container, apiUrl, tables) {
  // テスト履歴データのテーブルインデックス（システム操作履歴を使用）
  const testHistoryTableIndex = 12;

  // 1. 再描画関数の定義
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.操作日時 ? new Date(r.操作日時).toLocaleString() : ""}</td>
        <td>${r.操作内容 || ""}</td>
        <td>${r.操作対象ID || ""}</td>
        <td>1</td>
        <td>8.5%</td>
        <td>12.3</td>
        <td>${r.処理時間 || 0}ms</td>
        <td>
          <span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; background: ${r.処理結果 === '成功' ? '#00aa44' : '#ff4444'}; color: white;">
            ${r.処理結果 || "完了"}
          </span>
        </td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(testHistoryTableIndex).then(rows => {
    if (rows) {
      renderTestHistory(rows);
    }
  });

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value;
    window.aivicApi.list(testHistoryTableIndex).then(rows => {
      if (rows) {
        const filtered = rows.filter(r => 
          JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
        );
        renderTestHistory(filtered);
      }
    });
  });

  // 4. 全店舗選択チェックボックス
  container.querySelector("#store-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".store-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 5. テスト実行機能
  container.querySelector("#btn-execute-test").addEventListener("click", async () => {
    // バリデーション
    const model = container.querySelector("#select-model").value;
    const category = container.querySelector("#select-category").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const dataset = container.querySelector('input[name="dataset"]:checked');
    const selectedStores = container.querySelectorAll(".store-checkbox:checked");

    // エラーチェック
    if (!model) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return;
    }
    if (!category) {
      showError("商品カテゴリが未選択です。カテゴリを選択してください。");
      return;
    }
    if (!startDate || !endDate) {
      showError("テスト期間を設定してください。");
      return;
    }
    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください。");
      return;
    }
    if (!dataset) {
      showError("テストデータセットが選択されていません。");
      return;
    }
    if (selectedStores.length === 0 && !container.querySelector("#store-all").checked) {
      showError("店舗が選択されていません。店舗を選択してください。");
      return;
    }

    // 存在しないモデルチェック
    if (model === "NonExistentModel_Test123") {
      showError("指定されたモデルが見つかりません。");
      return;
    }

    // テスト実行シミュレーション
    showSuccess("テストを実行中です...");

    // 実行時間シミュレーション
    const startTime = Date.now();

    setTimeout(() => {
      const endTime = Date.now();
      const executionTime = endTime - startTime;

      // 結果表示
      container.querySelector("#metric-mape").textContent = "8.5%";
      container.querySelector("#metric-rmse").textContent = "12.3";
      container.querySelector("#metric-mae").textContent = "9.7";
      container.querySelector("#metric-r2").textContent = "0.92";
      container.querySelector("#execution-time").textContent = `${executionTime}ms`;
      container.querySelector("#model-parameters").innerHTML = `
        モデル: ${model}<br>
        学習率: 0.001<br>
        エポック数: 100<br>
        バッチサイズ: 32<br>
        隠れ層: 128
      `;

      // グラフ描画
      drawComparisonChart();

      // テスト履歴に追加
      const testRecord = {
        ユーザーID: "user-001",
        操作種別: "モデルテスト実行",
        操作画面: "モデルテスト機能",
        操作内容: `モデル: ${model}, 期間: ${startDate}〜${endDate}`,
        処理結果: "成功",
        処理時間: executionTime,
        操作日時: new Date().toISOString()
      };

      window.aivicApi.save(testHistoryTableIndex, testRecord).then(() => {
        window.aivicApi.list(testHistoryTableIndex).then(renderTestHistory);
      });

      showSuccess("テストが完了しました。");
    }, 2000);
  });

  // 6. グラフ描画関数
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const dates = [];
    const actual = [];
    const predicted = [];

    for (let i = 0; i < 30; i++) {
      dates.push(i);
      actual.push(Math.sin(i * 0.2) * 50 + 100 + Math.random() * 20);
      predicted.push(Math.sin(i * 0.2) * 45 + 105 + Math.random() * 15);
    }

    // グラフ設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績値線描画
    ctx.strokeStyle = '#00aa44';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actual.length; i++) {
      const x = padding + (i / (actual.length - 1)) * chartWidth;
      const y = canvas.height - padding - (actual[i] / 200) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値線描画
    ctx.strokeStyle = '#ff6a00';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predicted.length; i++) {
      const x = padding + (i / (predicted.length - 1)) * chartWidth;
      const y = canvas.height - padding - (predicted[i] / 200) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '14px sans-serif';
    ctx.fillText('実績値', padding + 20, padding - 20);
    ctx.fillStyle = '#00aa44';
    ctx.fillRect(padding, padding - 30, 15, 3);

    ctx.fillStyle = '#d0e4ff';
    ctx.fillText('予測値', padding + 100, padding - 20);
    ctx.fillStyle = '#ff6a00';
    ctx.fillRect(padding + 80, padding - 30, 15, 3);
  }

  // 7. エクスポート機能
  container.querySelector("#btn-export").addEventListener("click", () => {
    window.aivicApi.list(testHistoryTableIndex).then(rows => {
      if (rows) {
        const csvContent = "\uFEFF" + [
          "テスト日時,モデル名,操作内容,処理結果,処理時間",
          ...rows.map(r => `"${r.操作日時}","${r.操作内容}","${r.操作対象ID}","${r.処理結果}","${r.処理時間}"`)
        ].join("\n");

        const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = "model_test_results.csv";
        link.click();

        showSuccess("テスト結果をエクスポートしました。");
      }
    });
  });

  // 8. イベントデリゲーション（削除・詳細表示）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    const detailBtn = e.target.closest(".view-detail-btn");

    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(testHistoryTableIndex, id);
      window.aivicApi.list(testHistoryTableIndex).then(renderTestHistory);
      showSuccess("テスト履歴を削除しました。");
    }

    if (detailBtn) {
      const id = detailBtn.dataset.id;
      showSuccess("詳細画面は開発中です。");
    }
  });

  // ユーティリティ関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  function showSuccess(message) {
    const successDiv = container.querySelector("#success-message");
    successDiv.textContent = message;
    successDiv.classList.remove("hidden");
    setTimeout(() => successDiv.classList.add("hidden"), 3000);
  }

  // 初期日付設定
  const today = new Date();
  const lastMonth = new Date(today.getFullYear(), today.getMonth() - 1, today.getDate());
  container.querySelector("#input-start-date").value = lastMonth.toISOString().split('T')[0];
  container.querySelector("#input-end-date").value = today.toISOString().split('T')[0];
}
